.page {
  --cw-navy: #071a2d;
  --cw-aqua: #16dde3;
  --cw-ink: #10263a;
  --cw-muted: #637482;
  --cw-line: #d8e1e7;
  --cw-bg: #f4f8fb;
  min-width: 0;
  min-height: 100vh;
  max-width: none;
  margin: 0;
  padding: clamp(0.75rem, 2vw, 2rem);
  background: var(--cw-bg);
  color: var(--cw-ink);
}

.header {
  display: flex;
  max-width: 92rem;
  margin: 0 auto 1rem;
  padding: clamp(1rem, 3vw, 2rem);
  gap: 1rem;
  align-items: flex-start;
  justify-content: space-between;
  border-radius: 1rem;
  background: var(--cw-navy);
  color: white;
}

.header h1 {
  max-width: 52rem;
  margin: 0.15rem 0 0.45rem;
  font-size: clamp(1.55rem, 4vw, 2.8rem);
  line-height: 1.08;
}

.eyebrow {
  margin: 0;
  color: var(--cw-aqua);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.lede {
  max-width: 55rem;
  margin: 0;
  color: #c9d8e2;
}

.pending {
