html,
body {
  max-width: 100%;
  overflow-x: clip;
}

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 12% -4%, rgba(34, 211, 238, .12), transparent 30rem),
    radial-gradient(circle at 88% 8%, rgba(167, 139, 250, .11), transparent 34rem),
    linear-gradient(180deg, var(--bg-2) 0%, var(--bg) 30%, #070910 100%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.55;
  text-rendering: optimizeLegibility;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image:
    linear-gradient(rgba(255,255,255,.016) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.012) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(to bottom, black, transparent 70%);
}

::selection {
  background: rgba(34, 211, 238, .28);
  color: var(--text);
}

.page-header,
main,
footer {
  width: min(1240px, calc(100% - 40px));
  margin-inline: auto;
}

.page-header {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 32px;
  align-items: start;
  padding: 58px 0 38px;

  border-bottom: 1px solid var(--border);
}

.page-header::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -1px;
  width: min(260px, 42vw);
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--cyan), var(--violet), transparent);
  box-shadow: 0 0 24px rgba(34, 211, 238, .32);
}

h1, h2, h3, p { margin-top: 0; }

h1 {
  max-width: 920px;
  margin-bottom: 14px;
  font-size: clamp(2.25rem, 6vw, 4.7rem);
  line-height: .98;
  letter-spacing: -.055em;
  background: linear-gradient(105deg, #ffffff 0%, #e0f2fe 50%, #c4b5fd 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  overflow-wrap: anywhere;
}

h2 {
  margin-bottom: 0;
  font-size: clamp(1.45rem, 2.5vw, 2rem);
  line-height: 1.14;
  letter-spacing: -.035em;
}

h3 {
  margin-bottom: 8px;
  font-size: 1.03rem;
}

code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.eyebrow {
  margin-bottom: 9px;
  color: var(--cyan);
  font-size: .76rem;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.lede,
.muted,
.footnote { color: var(--muted); }

.lede {
  max-width: 780px;
  margin-bottom: 0;
  font-size: clamp(1rem, 2vw, 1.18rem);
}

.footnote {
  margin: 18px 0 0;
  font-size: .85rem;
  line-height: 1.65;
}

.status-pill {
  position: sticky;
  top: 18px;
  z-index: 4;
  max-width: 100%;
  padding: 10px 15px;
  border: 1px solid rgba(34, 211, 238, .28);

  border-radius: 999px;
  background: linear-gradient(135deg, rgba(34, 211, 238, .12), rgba(96, 165, 250, .08)), rgba(17, 24, 39, .88);
  box-shadow: 0 12px 32px rgba(0, 0, 0, .24), inset 0 1px rgba(255,255,255,.05);
  color: #dffaff;
  font-size: .86rem;
  font-weight: 800;
  white-space: nowrap;
  backdrop-filter: blur(14px);
}

main { padding: 10px 0 72px; }
section { margin-top: 54px; min-width: 0; }

.section-heading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 24px;
  min-width: 0;
  margin-bottom: 20px;
}

.section-heading.compact { align-items: center; }
.section-heading > * { min-width: 0; }
.section-heading .muted { max-width: 620px; margin-bottom: 0; }

.summary-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}

.summary-card,
.panel,
.milestone-card,
.overall-progress,
.table-wrap {
  position: relative;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--card-accent, var(--blue)) 10%, transparent), transparent 42%),
    linear-gradient(180deg, rgba(30, 41, 59, .76), rgba(15, 23, 42, .84));
  box-shadow: var(--shadow), inset 0 1px rgba(255,255,255,.035);
}

.summary-card {
  --card-accent: var(--blue);
  min-height: 132px;
  padding: 20px;
  overflow: hidden;
}

.summary-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--card-accent);
  box-shadow: 0 0 24px color-mix(in srgb, var(--card-accent) 60%, transparent);
}

.summary-card::after {
  content: "";
  position: absolute;
  right: -26px;
  top: -34px;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--card-accent) 12%, transparent);
  filter: blur(2px);
}

.summary-card:nth-child(1) { --card-accent: var(--cyan); }
.summary-card:nth-child(2) { --card-accent: var(--green); }
.summary-card:nth-child(3) { --card-accent: var(--blue); }
.summary-card:nth-child(4) { --card-accent: var(--rose); }
.summary-card:nth-child(5) { --card-accent: var(--amber); }

.summary-card:nth-child(6) { --card-accent: var(--violet); }

.summary-card .value {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 18px;
  color: var(--text);
  font-size: clamp(1.8rem, 3vw, 2.2rem);
  font-weight: 850;
  letter-spacing: -.045em;
}

.summary-card .label {
  position: relative;
  z-index: 1;
  color: color-mix(in srgb, var(--card-accent) 42%, #dbe5f4);
  font-size: .82rem;
  font-weight: 650;
}

.overall-progress {
  --card-accent: var(--cyan);
  margin-top: 15px;
  padding: 20px;
  overflow: hidden;
}

.progress-meta {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 11px;
  font-size: .9rem;
}

.progress-meta strong { color: #e8fbff; }

.progress-track {
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--track);
  box-shadow: inset 0 1px 4px rgba(0,0,0,.35);
}

.progress-bar {
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cyan), var(--blue) 45%, var(--violet) 78%, var(--green));
  box-shadow: 0 0 20px rgba(34, 211, 238, .25);
  transition: width .9s cubic-bezier(.22, 1, .36, 1);
}

.milestone-list { display: grid; gap: 14px; }

.milestone-card {
  --card-accent: var(--amber);
  padding: 20px;
  overflow: hidden;
}

.milestone-card.status-qualified { --card-accent: var(--green); }
.milestone-card.status-in-progress { --card-accent: var(--amber); }
.milestone-card.current-milestone-card {
  border-color: color-mix(in srgb, var(--card-accent) 46%, var(--border));
  box-shadow: 0 22px 58px rgba(0,0,0,.34), 0 0 0 1px color-mix(in srgb, var(--card-accent) 12%, transparent), inset 0 1px rgba(255,255,255,.04);
}

.milestone-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: linear-gradient(180deg, var(--card-accent), transparent 84%);
}

.milestone-top {
  display: flex;

  justify-content: space-between;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

.milestone-title {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.milestone-title h3 { margin: 0; min-width: 0; }
.milestone-title code { color: #f5f8ff; }

.badge {
  padding: 5px 9px;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(148, 163, 184, .06);
  font-size: .69rem;
  font-weight: 800;
  letter-spacing: .045em;
}

.badge.pass {
  color: #b7f7c8;
  border-color: rgba(74, 222, 128, .24);
  background: rgba(74, 222, 128, .08);
}

.badge.progress {
  color: #ffe49b;
  border-color: rgba(251, 191, 36, .26);
  background: rgba(251, 191, 36, .08);
}

.milestone-card .progress-track { margin-top: 15px; }
.milestone-card .progress-bar { background: linear-gradient(90deg, var(--card-accent), color-mix(in srgb, var(--card-accent) 58%, var(--blue))); }

.milestone-meta {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
  color: var(--muted);
  font-size: .78rem;
}

.milestone-meta span {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid rgba(148,163,184,.08);
  border-radius: 13px;
  background: rgba(2, 6, 23, .18);
}

.milestone-meta strong {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: .91rem;
  overflow-wrap: anywhere;
}

.two-column {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr);
  gap: 16px;
  min-width: 0;
}

.panel {
  --card-accent: var(--violet);
  padding: 22px;
  overflow: hidden;
}

.two-column > .panel:first-child { --card-accent: var(--cyan); }
.two-column > .panel:last-child { --card-accent: var(--violet); }

.panel::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  background: linear-gradient(90deg, var(--card-accent), transparent 70%);
}

.chart {
  width: 100%;
  min-width: 0;
  min-height: 300px;
  overflow: hidden;
}

.chart svg {
  display: block;
  width: 100%;
  max-width: 100%;
  height: 300px;
  overflow: visible;
}

.chart text {
  fill: var(--muted);
  font-size: 10px;
}

.chart .axis {
  stroke: rgba(148, 163, 184, .17);
  stroke-width: 1;
}

.chart .area { fill: url(#difficultyAreaGradient); }
.chart .line { fill: none; stroke: url(#difficultyLineGradient); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.chart .point { fill: var(--cyan); stroke: #07111f; stroke-width: 2.5; filter: drop-shadow(0 0 5px rgba(34,211,238,.45)); }
.chart .point.mid { fill: var(--amber); filter: drop-shadow(0 0 5px rgba(251,191,36,.38)); }
.chart .point.high { fill: var(--rose); filter: drop-shadow(0 0 5px rgba(251,113,133,.4)); }
.chart .score { fill: #ecfeff; font-weight: 750; }
.chart .x-label { fill: #c7d2e3; }

.timing-list { display: grid; gap: 0; }

.timing-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  gap: 20px;
  align-items: baseline;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.timing-row:last-child { border-bottom: 0; }
.timing-row span { color: var(--muted); }
.timing-row strong { color: #ede9fe; text-align: right; overflow-wrap: anywhere; }

.table-wrap {
  --card-accent: var(--rose);
  width: 100%;
  overflow: hidden;
}

.table-wrap::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  background: linear-gradient(90deg, var(--rose), var(--amber), transparent 80%);
}

table {
  width: 100%;
  max-width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  background: transparent;

}

th,
td {
  padding: 14px 15px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border);
  font-size: .84rem;
  overflow-wrap: anywhere;
  word-break: break-word;
}

th {
  color: #b8c4d6;
  background: rgba(15, 23, 42, .64);
  font-size: .72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .09em;
}

th:nth-child(1), td:nth-child(1) { width: 12%; }
th:nth-child(2), td:nth-child(2) { width: 17%; }
th:nth-child(3), td:nth-child(3) { width: 15%; }
th:nth-child(4), td:nth-child(4) { width: 38%; }
th:nth-child(5), td:nth-child(5) { width: 18%; }
tr:last-child td { border-bottom: 0; }
tbody tr { transition: background .2s ease; }
tbody tr:hover { background: rgba(248, 113, 113, .045); }

.stack-list { display: grid; gap: 0; }

.stack-item {
  min-width: 0;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.stack-item:last-child { border-bottom: 0; }
.stack-item strong,
.stack-item code { display: block; min-width: 0; max-width: 100%; overflow-wrap: anywhere; word-break: break-word; }
.stack-item .sub { margin-top: 5px; color: var(--muted); font-size: .78rem; overflow-wrap: anywhere; }

.timeline {
  display: grid;
  gap: 11px;
  min-width: 0;
}

.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: minmax(130px, 175px) minmax(120px, 165px) minmax(0, 1fr);
  gap: 14px;
  min-width: 0;
  padding: 15px 17px;
  border: 1px solid rgba(148,163,184,.1);
  border-left: 3px solid var(--subtle);
  border-radius: 0 var(--radius-small) var(--radius-small) 0;
  background: linear-gradient(90deg, rgba(148,163,184,.035), rgba(255,255,255,.012));
}

.timeline-item.failed {
  border-left-color: var(--rose);
  background: linear-gradient(90deg, rgba(251,113,133,.065), rgba(255,255,255,.01));
}

.timeline-item.passed {
  border-left-color: var(--green);
  background: linear-gradient(90deg, rgba(74,222,128,.045), rgba(255,255,255,.01));
}

.timeline-time,
.timeline-type {
  min-width: 0;
  color: var(--muted);
  font-size: .76rem;
  overflow-wrap: anywhere;
}

.timeline-type code { color: #c9d5e7; }
.timeline-summary { min-width: 0; font-size: .9rem; overflow-wrap: anywhere; }
.timeline-summary strong { color: #eef6ff; }
.timeline-summary small { display: block; margin-top: 5px; color: var(--muted); }

footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  min-width: 0;
  padding: 24px 0 42px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: .78rem;
}

footer p { min-width: 0; margin: 0; overflow-wrap: anywhere; }

.load-error {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 10;
  max-width: min(560px, calc(100vw - 36px));
  padding: 16px;
  border: 1px solid rgba(248,113,113,.5);
  border-radius: 14px;
  background: rgba(36, 23, 25, .96);
  color: var(--text);
  box-shadow: 0 16px 40px rgba(0,0,0,.45);
}

.load-error span { display: block; margin-top: 6px; color: var(--muted); }

.reveal {
  opacity: 0;
  transform: translateY(14px) scale(.995);
  transition:
    opacity .55s ease,
    transform .6s cubic-bezier(.22,1,.36,1),
    border-color .25s ease,
    box-shadow .25s ease;
  transition-delay: var(--reveal-delay, 0ms);
}

.reveal.is-visible {
  opacity: 1;
  transform: none;
}

@media (hover: hover) and (pointer: fine) {
  .summary-card,
  .milestone-card,
  .panel,
  .table-wrap {
    transition: transform .24s ease, border-color .24s ease, box-shadow .24s ease;
  }

  .summary-card:hover,
  .milestone-card:hover,
  .panel:hover,
  .table-wrap:hover {
    transform: translateY(-2px);
    border-color: color-mix(in srgb, var(--card-accent, var(--blue)) 32%, var(--border));
    box-shadow: 0 26px 64px rgba(0,0,0,.38), 0 0 0 1px color-mix(in srgb, var(--card-accent, var(--blue)) 8%, transparent);
  }
}

@media (max-width: 1040px) {
  .summary-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .two-column { grid-template-columns: 1fr; }
  .milestone-meta { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .page-header {
    grid-template-columns: 1fr;
    gap: 20px;
    padding-top: 34px;

}

.status-pill {
  position: static;
  justify-self: start;
  white-space: normal;
}

section { margin-top: 44px; }
.section-heading,
.section-heading.compact,
footer {
  align-items: flex-start;
  flex-direction: column;
}

.section-heading { display: flex; gap: 10px; }
.milestone-meta { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.table-wrap {
  border: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.table-wrap::before,
table thead { display: none; }

table,
tbody,
tr,
td {
  display: block;
  width: 100% !important;
  max-width: 100%;
}

table { table-layout: auto; }
tbody { display: grid; gap: 12px; }

tbody tr {
  padding: 12px 14px;
  border: 1px solid rgba(251,113,133,.18);
  border-radius: var(--radius-small);
  background: linear-gradient(145deg, rgba(251,113,133,.055), rgba(17,24,39,.86) 42%);
  box-shadow: 0 14px 32px rgba(0,0,0,.2);
}

td {
  display: grid;
  grid-template-columns: minmax(92px, 36%) minmax(0, 1fr);
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(148,163,184,.09);
  font-size: .82rem;
}

td:last-child { border-bottom: 0; }

td::before {
  color: var(--subtle);
  font-size: .69rem;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
}

td:nth-child(1)::before { content: "Milestone"; }
td:nth-child(2)::before { content: "Time"; }
td:nth-child(3)::before { content: "Component"; }
td:nth-child(4)::before { content: "Failure"; }
td:nth-child(5)::before { content: "Correction"; }

.timeline-item {
  grid-template-columns: 1fr;
  gap: 5px;
  padding: 14px;
}

  .timeline-time,
  .timeline-type { font-size: .72rem; }
}

@media (max-width: 520px) {
  .page-header,
  main,
  footer { width: min(100% - 24px, 1240px); }

  h1 { font-size: clamp(2.1rem, 12vw, 3.3rem); }
  .summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .summary-card { min-height: 118px; padding: 16px; }
  .summary-card .value { margin-top: 14px; }
  .overall-progress,
  .milestone-card,
  .panel { padding: 17px; }
  .milestone-top { align-items: flex-start; }
  .milestone-meta { gap: 8px; }
  .milestone-meta span { padding: 9px 10px; }
  .chart { min-height: 270px; }
  .chart svg { height: 270px; }
  .timing-row { gap: 12px; }
}

@media (max-width: 360px) {
  .summary-grid { grid-template-columns: 1fr; }
  .milestone-meta { grid-template-columns: 1fr 1fr; }
  td { grid-template-columns: 1fr; gap: 3px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
  .reveal { opacity: 1; transform: none; }
}

(() => {
  "use strict";

  const byId = (id) => document.getElementById(id);
  const escapeHtml = (value) => String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

  const formatTime = (value) => {
    if (!value) return "time not preserved";
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? value : date.toLocaleString();
  };

  const badgeClass = (status) => status === "QUALIFIED" ? "pass" : "progress";
  const statusClass = (status) => status === "QUALIFIED" ? "status-qualified" : "status-in-progress";
  const compactMilestone = (value) => String(value || "").replace(/^CWTV\.V/, "");

  function renderSummary(data) {
    const summary = data.summary;
    byId("current-milestone").textContent = `Current · ${summary.current_milestone}`;
    const cards = [
      ["Tracked milestones", summary.tracked_milestones],
      ["Qualified", summary.qualified_milestones],
      ["Passed events", summary.passed_events],
      ["Failed events", summary.failed_events],
      ["Corrections", summary.corrections],
      ["Commits", summary.commits],
    ];
    byId("summary-grid").innerHTML = cards.map(([label, value]) => `
      <article class="summary-card">
        <span class="label">${escapeHtml(label)}</span>
        <span class="value">${escapeHtml(value)}</span>
      </article>
    `).join("");

    const completion = Number(summary.tracked_completion_percent || 0);
    byId("overall-progress-label").textContent = `${completion.toFixed(1)}%`;
    requestAnimationFrame(() => {
      byId("overall-progress-bar").style.width = `${Math.max(0, Math.min(100, completion))}%`;
    });
    byId("ledger-head").textContent = `${data.ledger.head_event_id} · ${data.ledger.event_count} events`;
  }

  function renderMilestones(data) {
    byId("milestone-list").innerHTML = data.milestones.map((item) => {
      const currentClass = item.milestone === data.summary.current_milestone ? "current-milestone-card" : "";
      const progress = Math.max(0, Math.min(100, Number(item.progress_percent) || 0));
      return `
        <article class="milestone-card ${statusClass(item.status)} ${currentClass}">
          <div class="milestone-top">
            <div class="milestone-title">
              <h3><code>${escapeHtml(item.milestone)}</code></h3>
              <span class="badge ${badgeClass(item.status)}">${escapeHtml(item.status)}</span>
            </div>
            <strong>${escapeHtml(item.progress_percent)}%</strong>
          </div>
          <div class="progress-track"><div class="progress-bar" data-progress="${progress}"></div></div>
          <div class="milestone-meta">
            <span>Difficulty<strong>${escapeHtml(item.observed_difficulty)}/5</strong></span>
            <span>Failures<strong>${escapeHtml(item.failure_count)}</strong></span>
            <span>Corrections<strong>${escapeHtml(item.correction_count)}</strong></span>
            <span>Elapsed<strong>${escapeHtml(item.elapsed_label)}</strong></span>
            <span>Command runtime<strong>${escapeHtml(item.recorded_command_runtime_label)}</strong></span>
          </div>
        </article>
      `;
    }).join("");

    requestAnimationFrame(() => {
      document.querySelectorAll(".milestone-card .progress-bar[data-progress]").forEach((bar) => {
        bar.style.width = `${bar.dataset.progress}%`;
      });
    });
  }

  function renderDifficulty(data) {

  const container = byId("difficulty-chart");
  const items = data.milestones;
  if (!container || !items.length) return;

  const width = Math.max(300, Math.floor(container.getBoundingClientRect().width || 300));
  const height = width < 430 ? 270 : 300;
  const left = width < 430 ? 28 : 34;
  const right = width < 430 ? 12 : 18;
  const top = 22;
  const bottom = width < 430 ? 52 : 44;
  const chartHeight = height - top - bottom;
  const usableWidth = Math.max(1, width - left - right);
  const step = items.length > 1 ? usableWidth / (items.length - 1) : usableWidth;
  const y = (score) => top + chartHeight - ((Number(score) - 1) / 4) * chartHeight;
  const points = items.map((item, index) => ({
    x: items.length > 1 ? left + step * index : left + usableWidth / 2,
    y: y(item.observed_difficulty),
    item,
  }));
  const linePath = points.map((point, index) => `${index === 0 ? "M" : "L"}${point.x},${point.y}`).join(" ");
  const baseline = y(1);
  const areaPath = points.length > 1
    ? `${linePath} L${points.at(-1).x},${baseline} L${points[0].x},${baseline} Z`
    : "";
  const grid = [1, 2, 3, 4, 5].map((score) => {
    const yy = y(score);
    return `<line class="axis" x1="${left}" y1="${yy}" x2="${width - right}" y2="${yy}"></line><text x="4" y="${yy + 3}">${score}</text>`;
  }).join("");
  const marks = points.map((point, index) => {
    const score = Number(point.item.observed_difficulty);
    const severity = score >= 4 ? "high" : score >= 2.5 ? "mid" : "";
    const labelY = height - (index % 2 === 0 ? 20 : 8);
    return `
      <circle class="point ${severity}" cx="${point.x}" cy="${point.y}" r="4.5"></circle>
      <text class="x-label" x="${point.x}" y="${labelY}" text-anchor="middle">${escapeHtml(compactMilestone(point.item.milestone))}</text>
      <text class="score" x="${point.x}" y="${Math.max(12, point.y - 10)}" text-anchor="middle">${escapeHtml(point.item.observed_difficulty)}</text>
    `;
  }).join("");

  container.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" aria-hidden="true">
      <defs>
        <linearGradient id="difficultyLineGradient" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stop-color="#22d3ee"></stop>
          <stop offset="52%" stop-color="#60a5fa"></stop>
          <stop offset="100%" stop-color="#a78bfa"></stop>
        </linearGradient>
        <linearGradient id="difficultyAreaGradient" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#22d3ee" stop-opacity=".18"></stop>
          <stop offset="100%" stop-color="#22d3ee" stop-opacity="0"></stop>
        </linearGradient>
      </defs>
      ${grid}
      ${areaPath ? `<path class="area" d="${areaPath}"></path>` : ""}
      <path class="line" d="${linePath}"></path>
      ${marks}
    </svg>
  `;
}

function renderTiming(data) {
  const current = data.milestones.find((item) => item.milestone === data.summary.current_milestone) || data.milestones.at(-1);
  if (!current) {
    byId("timing-list").textContent = "No timing data recorded.";
    return;
  }
  const rows = [
    ["Current milestone", current.milestone],
    ["Elapsed", current.elapsed_label],
    ["Recorded command runtime", current.recorded_command_runtime_label],
    ["Active session time", current.active_session_label],
    ["Paused time", current.paused_label],
    ["Explicit breaks", current.session_data_present ? current.break_count : "not preserved"],
  ];
  byId("timing-list").innerHTML = rows.map(([label, value]) => `
    <div class="timing-row"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>
  `).join("");
}

function renderFailures(data) {

  const tbody = byId("failures-body");
  if (!data.failures.length) {
    tbody.innerHTML = `<tr><td colspan="5">No failed events recorded.</td></tr>`;
    return;
  }
  tbody.innerHTML = data.failures.map((event) => `
    <tr>
      <td><code>${escapeHtml(event.milestone)}</code></td>
      <td>${escapeHtml(formatTime(event.occurred_at))}</td>
      <td>${escapeHtml(event.component || "—")}</td>
      <td>${escapeHtml(event.summary)}</td>
      <td>${escapeHtml(event.correction || "—")}</td>
    </tr>
  `).join("");
}

function renderArtifacts(data) {
  const seen = new Set();
  const unique = data.artifacts.filter((event) => {
    const key = `${event.artifact?.name || ""}|${event.artifact?.sha256 || ""}|${event.event_type}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  byId("artifact-list").innerHTML = unique.length ? unique.map((event) => `
    <div class="stack-item">
      <strong><code>${escapeHtml(event.artifact.name)}</code></strong>
      <div class="sub">${escapeHtml(event.event_type)} · ${escapeHtml(formatTime(event.occurred_at))}</div>
      <div class="sub">${event.artifact.sha256 ? `SHA-256 ${escapeHtml(event.artifact.sha256)}` : "SHA-256 recorded after finalized archive verification"}</div>
    </div>
  `).join("") : `<div class="stack-item">No artifact events recorded.</div>`;
}

function renderCommits(data) {
  byId("commit-list").innerHTML = data.commits.length ? data.commits.map((event) => `
    <div class="stack-item">
      <strong><code>${escapeHtml(event.commit)}</code></strong>
      <div class="sub">${escapeHtml(event.summary)}</div>
      <div class="sub">${escapeHtml(formatTime(event.occurred_at))}</div>
    </div>
  `).join("") : `<div class="stack-item">No commit events recorded.</div>`;
}

function renderTimeline(data) {
  byId("timeline").innerHTML = data.events.map((event) => {
    const klass = event.result === "FAILED" ? "failed" : (event.result === "PASS" || event.result === "QUALIFIED" ? "passed" : "");
    const evidence = event.evidence?.length ? `<small>${escapeHtml(event.evidence.join(" · "))}</small>` : "";
    const duration = event.duration_seconds != null ? `<small>Duration: ${escapeHtml(event.duration_seconds)}s</small>` : "";
    return `
      <article class="timeline-item ${klass}">
        <div class="timeline-time">${escapeHtml(formatTime(event.occurred_at))}</div>
        <div class="timeline-type"><code>${escapeHtml(event.event_type)}</code></div>
        <div class="timeline-summary"><strong>${escapeHtml(event.milestone)}</strong> · ${escapeHtml(event.summary)}${duration}${evidence}</div>
      </article>
    `;
  }).join("");
}

function setupRevealAnimations() {
  const items = [...document.querySelectorAll(".summary-card, .overall-progress, .milestone-card, .panel, .table-wrap, .timeline-item")];
  items.forEach((item, index) => {
    item.classList.add("reveal");
    item.style.setProperty("--reveal-delay", `${Math.min(index % 6, 5) * 35}ms`);
  });

  if (!("IntersectionObserver" in window)) {
    items.forEach((item) => item.classList.add("is-visible"));
    return;
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }, { threshold: 0.06, rootMargin: "0px 0px -28px 0px" });

  items.forEach((item) => observer.observe(item));
}

  let dashboardData = null;
  let resizeTimer = null;

  function renderAll(data) {
    dashboardData = data;
    renderSummary(data);
    renderMilestones(data);
    renderDifficulty(data);
    renderTiming(data);
    renderFailures(data);
    renderArtifacts(data);
    renderCommits(data);
    renderTimeline(data);
    setupRevealAnimations();
  }

  window.addEventListener("resize", () => {
    if (!dashboardData) return;
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(() => renderDifficulty(dashboardData), 120);
  });

  fetch("./progress-data.json", { cache: "no-store" })
    .then((response) => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    })
    .then(renderAll)
    .catch((error) => {
      console.error(error);
      byId("load-error").hidden = false;
      byId("current-milestone").textContent = "Data unavailable";
    });
})();

