"""Database URL validation and redaction."""

from __future__ import annotations

from sqlalchemy.engine import URL, make_url

from cinewatch_api.settings import Settings, get_settings

POSTGRESQL_DRIVER = "postgresql+psycopg"


class DatabaseConfigurationError(RuntimeError):
    """Raised when the CineWatch PostgreSQL configuration is absent or invalid."""


def require_database_url(settings: Settings | None = None) -> URL:
    """Return the validated CineWatch PostgreSQL URL without opening a connection."""

    runtime_settings = settings or get_settings()
    if runtime_settings.database_url is None:
        raise DatabaseConfigurationError("DATABASE_URL is not configured")

    raw_url = runtime_settings.database_url.get_secret_value().strip()
    if not raw_url:
        raise DatabaseConfigurationError("DATABASE_URL is not configured")

    try:
        url = make_url(raw_url)
    except Exception as exc:  # SQLAlchemy raises several URL parsing exceptions.
        raise DatabaseConfigurationError("DATABASE_URL is invalid") from exc

    if url.drivername != POSTGRESQL_DRIVER:
        raise DatabaseConfigurationError(
            f"DATABASE_URL must use the {POSTGRESQL_DRIVER} driver"
        )
    if not url.database:
        raise DatabaseConfigurationError("DATABASE_URL must name a CineWatch database")

    return url


def safe_database_url(url: URL) -> str:
    """Render a database URL with credentials redacted for diagnostics."""

    return url.render_as_string(hide_password=True)

"""Deterministic provider-media gap and fallback naming authority."""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass
from typing import Literal

EntityType = Literal["person", "network", "movie", "tv"]
AssetKind = Literal["profile", "logo", "poster", "backdrop"]
Remediation = Literal["AWAITING_HUMAN_RESEARCH", "GENERATION_ALLOWED"]

_DIRECTORY_BY_ASSET: dict[AssetKind, str] = {
    "profile": "people",
    "logo": "networks",
    "poster": "posters",
    "backdrop": "backdrops",
}

_ALLOWED: set[tuple[EntityType, AssetKind]] = {
    ("person", "profile"),
    ("network", "logo"),
    ("movie", "poster"),
    ("movie", "backdrop"),
    ("tv", "poster"),
    ("tv", "backdrop"),
}


def slugify(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode("ascii")
    slug = re.sub(r"[^a-z0-9]+", "-", normalized.lower()).strip("-")
    return slug or "entity"


def remediation_for(asset_kind: AssetKind) -> Remediation:
    if asset_kind in {"logo", "backdrop"}:
        return "GENERATION_ALLOWED"
    return "AWAITING_HUMAN_RESEARCH"


@dataclass(frozen=True, slots=True)
class MediaGap:
    provider: str
    entity_type: EntityType
    provider_id: int
    entity_name: str
    asset_kind: AssetKind

    def __post_init__(self) -> None:
        if self.provider_id <= 0:
            raise ValueError("provider_id must be positive.")
        if (self.entity_type, self.asset_kind) not in _ALLOWED:
            raise ValueError(
                f"unsupported media gap combination: {self.entity_type}/{self.asset_kind}"
            )
        if not re.fullmatch(r"[a-z0-9]+", self.provider):
            raise ValueError("provider must be a lowercase alphanumeric code.")

    @property
    def remediation(self) -> Remediation:
        return remediation_for(self.asset_kind)

    @property
    def directory(self) -> str:
        return _DIRECTORY_BY_ASSET[self.asset_kind]

    @property
    def suggested_filename(self) -> str:
        return (
            f"{self.provider}-{self.entity_type}-{self.provider_id}-"
            f"{slugify(self.entity_name)}.webp"
        )

    @property
    def public_path(self) -> str:
        return f"/provider-fallbacks/{self.directory}/{self.suggested_filename}"

    def as_record(self) -> dict[str, object]:

"""OMDb provider adapter for governed secondary enrichment."""

from __future__ import annotations

from typing import cast

import httpx
from pydantic import SecretStr

from cinewatch_api.providers.errors import (
    ProviderAuthenticationError,
    ProviderConfigurationError,
    ProviderResponseError,
    ProviderUnavailableError,
)

OMDB_BASE_URL = "https://www.omdbapi.com/"


class OmdbClient:
    """Minimal server-only OMDb client; never a replacement for TMDb primary data."""

    def __init__(
        self,
        *,
        api_key: SecretStr | None,
        http_client: httpx.AsyncClient | None = None,
        timeout_seconds: float = 8.0,
    ) -> None:
        self._api_key = api_key
        self._client = http_client
        self._timeout_seconds = timeout_seconds

    def _credential(self) -> str:
        if self._api_key is None or not self._api_key.get_secret_value().strip():
            raise ProviderConfigurationError(
                provider="omdb",
                code="OMDB_CREDENTIAL_MISSING",
                message="OMDb is not configured for this runtime.",
            )
        return self._api_key.get_secret_value().strip()

    async def lookup_imdb(self, imdb_id: str) -> dict[str, object]:
        if not imdb_id.startswith("tt") or not imdb_id[2:].isdigit():
            raise ValueError("OMDb IMDb identity must have the form tt########.")

        owns_client = self._client is None
        client = self._client or httpx.AsyncClient(
            timeout=self._timeout_seconds,
            headers={"Accept": "application/json", "User-Agent": "CineWatch-TV/1"},
        )
        try:
            try:
                response = await client.get(
                    OMDB_BASE_URL, params={"apikey": self._credential(), "i": imdb_id}
                )
            except httpx.HTTPError as exc:
                raise ProviderUnavailableError(
                    provider="omdb",
                    code="OMDB_TRANSPORT_FAILED",
                    message="OMDb could not be reached.",
                ) from exc

            if response.status_code >= 500:
                raise ProviderUnavailableError(
                    provider="omdb",
                    code="OMDB_UNAVAILABLE",
                    message="OMDb returned a server failure.",
                    status_code=response.status_code,
                )
            if not response.is_success:
                raise ProviderResponseError(
                    provider="omdb",
                    code="OMDB_REQUEST_FAILED",
                    message="OMDb rejected the request.",
                    status_code=response.status_code,
                )
            try:
                payload = response.json()
            except ValueError as exc:

            )
        if response.status_code >= 500:
            raise ProviderUnavailableError(
                provider="tmdb",
                code="TMDB_UNAVAILABLE",
                message="TMDb returned a server failure.",
                status_code=response.status_code,
            )
        if not response.is_success:
            raise ProviderResponseError(
                provider="tmdb",
                code="TMDB_REQUEST_FAILED",
                message="TMDb rejected the request.",
                status_code=response.status_code,
            )
        try:
            payload = response.json()
        except ValueError as exc:
            raise ProviderResponseError(
                provider="tmdb",
                code="TMDB_INVALID_JSON",
                message="TMDb returned invalid JSON.",
                status_code=response.status_code,
            ) from exc
        if not isinstance(payload, dict):
            raise ProviderResponseError(
                provider="tmdb",
                code="TMDB_INVALID_PAYLOAD",
                message="TMDb returned an unexpected payload shape.",
                status_code=response.status_code,
            )
        return cast(dict[str, object], payload)
    finally:
        if owns_client:
            await client.aclose()

async def configuration(self) -> dict[str, object]:
    """Perform a low-cost authenticated probe without exposing the credential."""

    return await self.get_json("/configuration")

